	include 'all.macros'	EXPORT QDLoaderQDLoader	PROCQDUserID	equ $B001	phk	plb	pha	; space for result	PushWord #QDUserID	PushWord #0	_UserShutdown	pla	pha	; space for dir page stack size	pha	; space for addr of	dir page stack seg	pha	; space for starting addr	pha	pha	; space for user id	PushWord #QDUserID	; user id	PushLong #QDName	; ptr to path name	PushWord #0	_InitialLoad	bcs Die	pla	; ignore userid	pla	; put starting address	sta TableAddress	pla	sta TableAddress+2	pla	; ignore dir page	pla	; ignore dir page size	PushWord #0	; system call	PushWord #4	; install the patch	PushLong TableAddress	_SetTSPtr		_SetDefaultTPT			import TryItOut	jsl TryItOut			_Quit QuitParamsQuitParams	DC.L 0	DC.W 0QDName	str '1/QD.IN.RAM'TableAddress	DS.B 4Die		; 	pha	PushLong #ErrorString	_SysFailMgrErrorString	str 'Could not load.  Error was $'	ENDPTryItOut	PROC	DSect 0MyUserID	wordTestRgn1	longTestRgn2	long	lda >$C062	and #$0080	beq @1	brk $17@1	pha	_MMStartup	pla	sta MyUserID	tdc	clc	adc #$100	pha	; dpage	PushWord #$80	; mode	PushWord #0	; max width	pei MyUserID	; user id	_QDStartup	pha	; test the font caching stuff...	pha	_GetSysFont	_SetFont	PushLong #TestRect1	_EraseRect	pha	pha	_NewRgn	PullLong TestRgn1	pha	pha	_NewRgn	PullLong TestRgn2	PushLong TestRgn1	PushLong #TestRect2	_RectRgn	PushLong TestRgn2	PushLong #testRect3	_RectRgn	PushLong TestRgn1	PushLong TestRgn2	PushLong TestRgn1	_UnionRgn		PushLong TestRgn1	_setClip	PushLong #testrect1	_PaintRect	PushLong #ThisPat	_SetPenPat	PushLong #TestRect1	_PaintRect	pea 100	pea 100	_MoveTo	PushLong #testText	_DrawString	pha	pea 0	_ReadChar	pla	pei TestRgn1+2	pei TestRgn1	_DisposeRgn	pei TestRgn2+2	pei TestRgn2	_DisposeRgn	_QDShutdown	rtlTestRect1	dc.w 0,0,200,640TestRect2	dc.w 10,10,100,300TestRect3	dc.w 50,100,150,310TestText	str 'Strings are now working fine!'ThisPat	dc.w $1122,$3344	dc.w $1122,$3344	dc.w $1122,$3344	dc.w $1122,$3344	dc.w $3344,$1122	dc.w $3344,$1122	dc.w $3344,$1122	dc.w $3344,$1122	ENDP	END					